export function understandFreeTextJourney(text,flow={}){
 const educationalOnly=/\b(?:explain|what is|how (?:does|do|is|are)|learn|learning|generally|general information|guide me)\b/i.test(String(text||''))&&!/\b(?:plans?|polic(?:y|ies)|options?|recommend|suggest|compare|premium quote|buy)\b/i.test(String(text||''));if(educationalOnly)return null;
 const value=String(text||'').trim();if(!value||/don['’]?t|do not|not now|لا أريد|لا تعرض/i.test(value))return null;
 if(/\b(?:renew|renewal|extend)\b.{0,35}\b(?:policy|insurance|cover)|\brenew my policy\b|(?:تجديد|جدد).{0,25}(?:وثيقة|تأمين)/i.test(value))return {type:'renewal'};
 if(/\b(?:motor|car|vehicle|auto)\b.{0,45}\b(?:insurance|cover|plans?|polic(?:y|ies)|options?|buy)|\b(?:buy|need|want|show|find)\b.{0,35}\b(?:motor|car|vehicle)\s+(?:insurance|cover)|(?:تأمين المركبات|تأمين سيارة|تأمين السيارة)/i.test(value))return {type:'motor'};
 const contextualLife=flow?.category==='life'&&['catalogue','recommendations','addons','calculator','review','plans','selected'].includes(flow?.stage),explicitLife=/\b(?:life insurance|life protection|life cover)\b|(?:تأمين الحياة|حماية الحياة)/i.test(value),education=/\b(?:education|university|school|college|children['’]?s future|child['’]?s future)\b|(?:تعليم|جامعة|دراسة|مستقبل الأطفال)/i.test(value),combined=/\b(?:saving|savings|investment|invest|wealth|future fund)\b|(?:ادخار|استثمار|ثروة)/i.test(value),family=/\b(?:family|dependants?|loved ones|protect my family|income protection)\b|(?:أسرة|عائلة|المعالين|حماية أسرتي)/i.test(value),planLanguage=/\b(?:plans?|polic(?:y|ies)|options?|recommend(?:ation|ed|s)?|suggest(?:ion|ed|s)?|best|top[- ]seller|popular|compare|premium|coverage|cover|buy|need|want|show|find|protect|save)\b|(?:خطط|وثائق|خيارات|أفضل|الأكثر مبيعاً|قارن|قسط|تغطية|شراء|أريد|أحتاج|احم|ادخر)/i.test(value);
 if(!(explicitLife||(contextualLife&&planLanguage)||((education||combined||family)&&planLanguage)))return null;
 const goal=education?'education':combined?'combined':family?'protect':flow?.lifeGoal&&flow.lifeGoal!=='all'?flow.lifeGoal:null,preference=/\b(?:top[- ]seller|most popular|popular|most sold)\b|(?:الأكثر مبيعاً|الأكثر شعبية)/i.test(value)?'seller':/\b(?:cheapest|lowest premium|affordable|budget|value)\b|(?:الأرخص|أقل قسط|اقتصادي|ميزانية)/i.test(value)?'value':/\b(?:best|recommend|suggest|suitable|right for me)\b|(?:أفضل|أنسب|موصى|اقترح)/i.test(value)?'best':'browse';
 return {type:'life',goal,preference};
}
export const isLifePolicyListRequest=(text,flow={})=>understandFreeTextJourney(text,flow)?.type==='life';

function removeInternalDataLabels(root){
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;
 while((node=walker.nextNode()))node.nodeValue=node.nodeValue.replace(/HIMAYA\s*·\s*AI\b/gi,'HIMAYA ·').replace(/\bAI BEST FIT\b/gi,'HIMAYA RECOMMENDATION').replace(/\bAI BEST START\b/gi,'HIMAYA SUGGESTION').replace(/\bAI STARTING POINT\b/gi,'HIMAYA SUGGESTION').replace(/\bAI[- ]GUIDED\b/gi,'HIMAYA-GUIDED').replace(/\bAI[- ]RANKED\b/gi,'HIMAYA-RANKED').replace(/\bAI[- ]PREPARED\b/gi,'HIMAYA-PREPARED').replace(/\bAI[- ]SELECTED\b/gi,'HIMAYA-SELECTED').replace(/\bAI ASSISTED\b/gi,'HIMAYA ASSISTED').replace(/\bAI\b/g,'Himaya').replace(/بالذكاء الاصطناعي/g,'بواسطة حماية').replace(/الذكاء الاصطناعي/g,'حماية').replace(/\b(?:synthetic|simulated)\b/gi,'').replace(/اصطناعي(?:ة|اً|ا)?/g,'').replace(/\s{2,}/g,' ');
}
export const applyHimayaTerminology=removeInternalDataLabels;

function removeRetiredCustomerSections(root){
 root.querySelectorAll('.explore-policy-catalogue .synthetic-disclosure').forEach(section=>section.remove());
 const form=root.querySelector('#customer-profile-form'),section=form?.querySelector('.profile-section:nth-of-type(4)');
 if(!form||!section)return;
 for(const control of section.querySelectorAll('[name]')){const hidden=document.createElement('input');hidden.type='hidden';hidden.name=control.name;hidden.value=control.value;form.append(hidden);}
 section.remove();
}

