  const hasProfile=Boolean(this.state.registered||this.state.authenticated||this.state.profile?.age||this.state.profile?.monthlyIncome),profileGoal=['protect','combined','education'].includes(this.state.profile?.goal)?this.state.profile.goal:null,resolvedGoal=intent.goal||(hasProfile?profileGoal:null),goalName={protect:'family protection',combined:'protection and savings',education:'education planning'}[resolvedGoal]||'Life Insurance',preferenceName={seller:'top-seller',value:'value',best:'best-fit',browse:'policy'}[intent.preference];
