  this.state.exploreView='response';this.state.exploreJourney=null;this.state.purchaseFlow=hasProfile?{stage:'recommendations',category:'life',lifeGoal:resolvedGoal||'protect',renewal:false,journeyMode:'chat',intentPreference:intent.preference,aiAssisted:true,synthetic:true}:{stage:'catalogue',category:'life',lifeGoal:resolvedGoal||'all',catalogueFilter:resolvedGoal||'all',catalogueVisible:9,guestCatalogue:true,intentPreference:intent.preference,aiAssisted:true,synthetic:true};
